package com.parcelproof;
import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/auth") class AuthController{final AuthService auth;final UserRepo users;final Mapper map;AuthController(AuthService a,UserRepo u,Mapper m){auth=a;users=u;map=m;}@PostMapping("/register") ApiResponse<AuthResponse> reg(@Valid @RequestBody RegisterRequest r){return ApiResponse.ok("Registered",auth.register(r));}@PostMapping("/login") ApiResponse<AuthResponse> log(@Valid @RequestBody LoginRequest r){return ApiResponse.ok("Login",auth.login(r));}@GetMapping("/me") ApiResponse<UserResponse> me(Authentication a){return ApiResponse.ok("Me",map.user(users.findByEmail(a.getName()).orElseThrow()));}}
@RestController @RequestMapping("/api/users") class UserController{final UserRepo users;final Mapper map;UserController(UserRepo u,Mapper m){users=u;map=m;}@GetMapping @PreAuthorize("hasRole('ADMIN')") ApiResponse<?> all(){return ApiResponse.ok("Users",users.findAll().stream().map(map::user).toList());}@GetMapping("/drivers") @PreAuthorize("hasAnyRole('ADMIN','DISPATCHER')") ApiResponse<?> drivers(){return ApiResponse.ok("Drivers",users.findByRole(UserRole.DRIVER).stream().map(map::user).toList());}@GetMapping("/customers") @PreAuthorize("hasAnyRole('ADMIN','DISPATCHER')") ApiResponse<?> customers(){return ApiResponse.ok("Customers",users.findByRole(UserRole.CUSTOMER).stream().map(map::user).toList());}@PutMapping("/{id}/status") @PreAuthorize("hasRole('ADMIN')") ApiResponse<?> status(@PathVariable Long id,@RequestParam UserStatus status){AppUser u=users.findById(id).orElseThrow();u.status=status;users.save(u);return ApiResponse.ok("Updated",map.user(u));}}
@RestController @RequestMapping("/api/parcels") class ParcelController{final ParcelService svc;final UserRepo users;ParcelController(ParcelService s,UserRepo u){svc=s;users=u;}AppUser cur(Authentication a){return users.findByEmail(a.getName()).orElseThrow();}@PostMapping @PreAuthorize("hasAnyRole('ADMIN','DISPATCHER')") ApiResponse<?> create(@Valid @RequestBody ParcelRequest r,Authentication a){return ApiResponse.ok("Created",svc.create(r,cur(a)));}@GetMapping ApiResponse<?> list(Authentication a){return ApiResponse.ok("Parcels",svc.list(cur(a)));}@GetMapping("/{id}") ApiResponse<?> get(@PathVariable Long id,Authentication a){return ApiResponse.ok("Parcel",svc.get(id,cur(a)));}@GetMapping("/tracking/{code}") ApiResponse<?> track(@PathVariable String code){return ApiResponse.ok("Tracking",svc.track(code));}@PutMapping("/{id}/assign-driver") @PreAuthorize("hasAnyRole('ADMIN','DISPATCHER')") ApiResponse<?> assign(@PathVariable Long id,@Valid @RequestBody AssignDriverRequest r,Authentication a){return ApiResponse.ok("Assigned",svc.assign(id,r.driverId(),cur(a)));}@PutMapping("/{id}/status") ApiResponse<?> status(@PathVariable Long id,@Valid @RequestBody StatusUpdateRequest r,Authentication a){return ApiResponse.ok("Status",svc.status(id,r.status(),r.note(),cur(a)));}@PutMapping("/{id}/cancel") @PreAuthorize("hasRole('ADMIN')") ApiResponse<?> cancel(@PathVariable Long id,Authentication a){return ApiResponse.ok("Cancelled",svc.status(id,ParcelStatus.CANCELLED,"Cancelled",cur(a)));}@PutMapping("/{id}/return") @PreAuthorize("hasAnyRole('ADMIN','DISPATCHER')") ApiResponse<?> ret(@PathVariable Long id,Authentication a){return ApiResponse.ok("Returned",svc.status(id,ParcelStatus.RETURNED,"Returned",cur(a)));}@GetMapping("/{id}/timeline") ApiResponse<?> tl(@PathVariable Long id,Authentication a){return ApiResponse.ok("Timeline",svc.timeline(id,cur(a)));}}
@RestController @RequestMapping("/api/driver") @PreAuthorize("hasRole('DRIVER')") class DriverController{final ParcelService svc;final DashboardService dash;final UserRepo users;DriverController(ParcelService s,DashboardService d,UserRepo u){svc=s;dash=d;users=u;}AppUser cur(Authentication a){return users.findByEmail(a.getName()).orElseThrow();}@GetMapping("/dashboard") ApiResponse<?> dashboard(Authentication a){return ApiResponse.ok("Driver dashboard",dash.driver(cur(a)));}@GetMapping("/parcels") ApiResponse<?> parcels(Authentication a){return ApiResponse.ok("Parcels",svc.list(cur(a)));}@GetMapping("/route") ApiResponse<?> route(Authentication a){return ApiResponse.ok("Route",svc.list(cur(a)));}@PutMapping("/parcels/{id}/pickup") ApiResponse<?> pickup(@PathVariable Long id,Authentication a){return ApiResponse.ok("Picked",svc.status(id,ParcelStatus.PICKED_UP,"Picked up",cur(a)));}@PutMapping("/parcels/{id}/in-transit") ApiResponse<?> transit(@PathVariable Long id,Authentication a){return ApiResponse.ok("Transit",svc.status(id,ParcelStatus.IN_TRANSIT,"In transit",cur(a)));}@PutMapping("/parcels/{id}/out-for-delivery") ApiResponse<?> out(@PathVariable Long id,Authentication a){return ApiResponse.ok("Out",svc.status(id,ParcelStatus.OUT_FOR_DELIVERY,"Out for delivery",cur(a)));}@PostMapping("/parcels/{id}/verify-delivery") ApiResponse<?> verify(@PathVariable Long id,@Valid @RequestBody VerifyDeliveryRequest r,Authentication a){return ApiResponse.ok("Verified",svc.verify(id,r,cur(a)));}@PostMapping("/parcels/{id}/failed-attempt") ApiResponse<?> fail(@PathVariable Long id,@Valid @RequestBody FailedAttemptRequest r,Authentication a){return ApiResponse.ok("Failed",svc.fail(id,r,cur(a)));}}
@RestController @RequestMapping("/api/tracking") class TrackingController{final ParcelService svc;TrackingController(ParcelService s){svc=s;}@GetMapping("/{code}") ApiResponse<?> track(@PathVariable String code){return ApiResponse.ok("Tracking",svc.track(code));}@GetMapping("/{code}/timeline") ApiResponse<?> tl(@PathVariable String code){return ApiResponse.ok("Timeline",svc.publicTimeline(code));}}
@RestController @RequestMapping("/api/dashboard") class DashboardController{final DashboardService dash;final UserRepo users;DashboardController(DashboardService d,UserRepo u){dash=d;users=u;}AppUser cur(Authentication a){return users.findByEmail(a.getName()).orElseThrow();}@GetMapping("/admin") @PreAuthorize("hasAnyRole('ADMIN','DISPATCHER')") ApiResponse<?> admin(){return ApiResponse.ok("Admin dashboard",dash.admin());}@GetMapping("/dispatcher") @PreAuthorize("hasAnyRole('ADMIN','DISPATCHER')") ApiResponse<?> dispatcher(){return ApiResponse.ok("Dispatcher dashboard",dash.admin());}@GetMapping("/customer") @PreAuthorize("hasRole('CUSTOMER')") ApiResponse<?> cust(Authentication a){return ApiResponse.ok("Customer dashboard",dash.customer(cur(a)));}}
@RestController @RequestMapping("/api/reports") @PreAuthorize("hasAnyRole('ADMIN','DISPATCHER')") class ReportController{final ParcelRepo parcels;final AttemptRepo attempts;ReportController(ParcelRepo p,AttemptRepo a){parcels=p;attempts=a;}@GetMapping("/parcel-status") ApiResponse<?> status(){return ApiResponse.ok("Status",Arrays.stream(ParcelStatus.values()).map(s->Map.of("status",s.name(),"parcel_count",parcels.countByStatus(s))).toList());}@GetMapping("/driver-performance") ApiResponse<?> perf(){return ApiResponse.ok("Performance",List.of());}@GetMapping("/failed-deliveries") ApiResponse<?> fail(){return ApiResponse.ok("Failed",attempts.findByAttemptStatus(AttemptStatus.FAILED));}@GetMapping("/daily-deliveries") ApiResponse<?> daily(){return ApiResponse.ok("Daily",List.of());}@GetMapping("/revenue") ApiResponse<?> rev(){return ApiResponse.ok("Revenue",List.of());}@GetMapping(value="/export/csv",produces="text/csv") ResponseEntity<String> csv(@RequestParam(defaultValue="daily")String type){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=parcelproof_"+type+".csv").body("type,count\n"+type+",0\n");}}
@RestController @RequestMapping("/api/audit-logs") @PreAuthorize("hasRole('ADMIN')") class AuditController{final AuditRepo logs;AuditController(AuditRepo l){logs=l;}@GetMapping ApiResponse<?> all(){return ApiResponse.ok("Logs",logs.findTop100ByOrderByCreatedAtDesc());}}
